package com.teamflow.planning.api;
import com.teamflow.planning.service.PlanningService; import jakarta.validation.Valid; import org.springframework.beans.factory.annotation.Value; import org.springframework.web.bind.annotation.*; import java.time.LocalDate; import java.time.OffsetDateTime; import java.util.*;
@RestController @RequestMapping("/planning") public class PlanningController{
 private final PlanningService service;private final UUID defaultOrg;public PlanningController(PlanningService s,@Value("${teamflow.organization.default-id}")UUID d){service=s;defaultOrg=d;}private UUID org(UUID o){return o==null?defaultOrg:o;}
 @PostMapping("/allocations") public AllocationResponse create(@RequestHeader(value="X-Organization-Id",required=false)UUID o,@Valid@RequestBody AllocationRequest r){return service.create(org(o),r);}
 @GetMapping("/allocations") public List<AllocationResponse> list(@RequestHeader(value="X-Organization-Id",required=false)UUID o,@RequestParam(required=false)UUID projectId,@RequestParam(required=false)String resourceType,@RequestParam(required=false)UUID resourceId,@RequestParam(required=false)LocalDate from,@RequestParam(required=false)LocalDate to){return service.list(org(o),projectId,resourceType,resourceId,from,to);}
 @PutMapping("/allocations/{id}") public AllocationResponse update(@RequestHeader(value="X-Organization-Id",required=false)UUID o,@PathVariable UUID id,@Valid@RequestBody AllocationUpdateRequest r){return service.update(org(o),id,r);}
 @PostMapping("/allocations/{id}/fixed") public AllocationResponse fixed(@RequestHeader(value="X-Organization-Id",required=false)UUID o,@PathVariable UUID id,@RequestParam boolean value,@RequestParam(required=false)OffsetDateTime expectedUpdatedAt){return service.fixed(org(o),id,value,expectedUpdatedAt);}
 @DeleteMapping("/allocations/{id}") public void cancel(@RequestHeader(value="X-Organization-Id",required=false)UUID o,@PathVariable UUID id,@RequestParam(required=false)OffsetDateTime expectedUpdatedAt){service.cancel(org(o),id,expectedUpdatedAt);}
 @PostMapping("/transports") public TransportResponse transport(@RequestHeader(value="X-Organization-Id",required=false)UUID o,@Valid@RequestBody TransportRequest r){return service.transport(org(o),r);}
 @GetMapping("/transports") public List<TransportResponse> transports(@RequestHeader(value="X-Organization-Id",required=false)UUID o){return service.transports(org(o));}
 @PutMapping("/transports/{id}") public TransportResponse updateTransport(@RequestHeader(value="X-Organization-Id",required=false)UUID o,@PathVariable UUID id,@Valid@RequestBody TransportUpdateRequest r){return service.updateTransport(org(o),id,r);}
 @DeleteMapping("/transports/{id}") public void cancelTransport(@RequestHeader(value="X-Organization-Id",required=false)UUID o,@PathVariable UUID id,@RequestParam(required=false)OffsetDateTime expectedUpdatedAt){service.cancelTransport(org(o),id,expectedUpdatedAt);}
 @PostMapping("/allocations/{id}/exceptions") public AllocationExceptionResponse exception(@RequestHeader(value="X-Organization-Id",required=false)UUID o,@PathVariable UUID id,@Valid@RequestBody AllocationExceptionRequest r){return service.exception(org(o),id,r);}
 @GetMapping("/allocations/{id}/exceptions") public List<AllocationExceptionResponse> exceptions(@RequestHeader(value="X-Organization-Id",required=false)UUID o,@PathVariable UUID id){return service.exceptions(org(o),id);}
 @PostMapping("/conflicts") public List<ConflictResponse> conflicts(@RequestHeader(value="X-Organization-Id",required=false)UUID o,@Valid@RequestBody AllocationRequest r){return service.conflicts(org(o),r);}
 @GetMapping("/availability") public AvailabilityResponse availability(@RequestHeader(value="X-Organization-Id",required=false)UUID o,@RequestParam String resourceType,@RequestParam UUID resourceId,@RequestParam LocalDate from,@RequestParam LocalDate to){return service.availability(org(o),resourceType,resourceId,from,to);}
 @PostMapping("/proposals") public ProposalResponse proposal(@RequestHeader(value="X-Organization-Id",required=false)UUID o){return service.generateProposal(org(o));}
 @GetMapping("/proposals") public List<ProposalResponse> proposals(@RequestHeader(value="X-Organization-Id",required=false)UUID o){return service.proposals(org(o));}
 @GetMapping("/proposals/{id}") public ProposalResponse proposal(@RequestHeader(value="X-Organization-Id",required=false)UUID o,@PathVariable UUID id){return service.proposal(org(o),id);}
 @PutMapping("/proposals/{id}") public ProposalResponse updateProposal(@RequestHeader(value="X-Organization-Id",required=false)UUID o,@PathVariable UUID id,@Valid@RequestBody ProposalUpdateRequest r){return service.updateProposal(org(o),id,r);}
 @PostMapping("/proposals/{id}/approve") public ProposalResponse approve(@RequestHeader(value="X-Organization-Id",required=false)UUID o,@PathVariable UUID id,@RequestBody(required=false) ProposalApprovalRequest r){return service.approve(org(o),id,r);}
 @PostMapping("/proposals/{id}/reject") public ProposalResponse reject(@RequestHeader(value="X-Organization-Id",required=false)UUID o,@PathVariable UUID id){return service.reject(org(o),id);}
 @PostMapping("/proposals/{id}/discard") public ProposalResponse discard(@RequestHeader(value="X-Organization-Id",required=false)UUID o,@PathVariable UUID id){return service.discard(org(o),id);}
}
